export const CATEGORY_LABELS: readonly string[] = SERVICE_CATEGORIES.map((c) => c.label)
export const isCategoryLabel = (s: string): boolean => CATEGORY_LABELS.includes(s)
export const categoryByLabel = (label: string): CatalogueCategory | null => SERVICE_CATEGORIES.find((c) => c.label === label) ?? null
/** The task types of one category, chosen by the category's label (how the console stores it). */
export const taskTypesFor = (categoryLabel: string): readonly CatalogueTask[] => categoryByLabel(categoryLabel)?.tasks ?? []
export const taskTypeBelongsTo = (taskCode: string, categoryLabel: string): boolean => taskTypesFor(categoryLabel).some((t) => t.code === taskCode)
